package main

import (
	"bytes"
	"compress/bzip2"
	"fmt"
	"io"
)

// packed holds the bzip2 stream of the text that want names. bzip2 of the
// standard library reads a stream and writes none, thus the test carries a
// stream that the bzip2 command wrote.
var packed = []byte{
	0x42, 0x5a, 0x68, 0x39, 0x31, 0x41, 0x59, 0x26, 0x53, 0x59, 0x25, 0x62,
	0xdd, 0xf4, 0x00, 0x00, 0x08, 0x51, 0x80, 0x00, 0x10, 0x40, 0x00, 0x1b,
	0x69, 0xb6, 0xc0, 0x20, 0x00, 0x22, 0x80, 0x0f, 0x50, 0xf5, 0x3f, 0x54,
	0x28, 0x69, 0xa6, 0x00, 0x0d, 0x2c, 0x59, 0x29, 0xbf, 0x6c, 0x1d, 0xdb,
	0x08, 0x7c, 0x5d, 0xc9, 0x14, 0xe1, 0x42, 0x40, 0x95, 0x8b, 0x77, 0xd0,
}

const want = "the quick brown fox\n"

func main() {
	r := bzip2.NewReader(bytes.NewReader(packed))
	out, err := io.ReadAll(r)
	if err != nil {
		fmt.Println("read:", err)
		return
	}
	fmt.Printf("text=%q equal=%v\n", out, string(out) == want)

	bad := bzip2.NewReader(bytes.NewReader([]byte("not a bzip2 stream")))
	if _, err := io.ReadAll(bad); err != nil {
		fmt.Println("a broken stream gives:", err)
	}
}
